pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        vm.assume(caddress != address(0));

        uint256 balanceBefore = address(c).balance;

        // Call transfer – it may revert; if it does, the property vacuously holds
        (bool success, ) = address(c).call(abi.encodeWithSelector(c.transfer.selector, from, caddress, _tos, v));
        if (success) {
            uint256 balanceAfter = address(c).balance;
            assertTrue(balanceAfter <= balanceBefore, "transfer should not increase contract balance");
        }
    }
}

