pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address from, address caddress, address[] memory _tos, uint256 v) public {
        vm.assume(_tos.length > 0);
        // Store allowances before the call
        uint256[] memory allowancesBefore = new uint256[](_tos.length);
        for (uint i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = address(caddress).staticcall(abi.encodeWithSignature("allowance(address,address)", from, _tos[i]));
            vm.assume(success && data.length == 32);
            allowancesBefore[i] = abi.decode(data, (uint256));
        }
        // Call transfer
        c.transfer(from, caddress, _tos, v);
        // Assert allowances are unchanged
        for (uint i = 0; i < _tos.length; i++) {
            (bool success, bytes memory data) = address(caddress).staticcall(abi.encodeWithSignature("allowance(address,address)", from, _tos[i]));
            vm.assume(success && data.length == 32);
            uint256 allowanceAfter = abi.decode(data, (uint256));
            assertTrue(allowancesBefore[i] == allowanceAfter);
        }
    }
}

